/**
 * A single naming-convention violation reported by the linter.
 */
export interface LintViolation {
    /** The identifier of the rule that was violated. */
    rule: string;
    /** A human readable description of the violation. */
    message: string;
    /** The offending name (declaration, property or enum constant). */
    name: string;
    /** The namespace of the model that contains the violation. */
    namespace: string;
    /** A path locating the offending element within the AST. */
    path: Array<string | number>;
    /** The severity of the violation. */
    severity: string;
}

/**
 * Matches a name that begins with an uppercase letter.
 */
const STARTS_WITH_UPPERCASE = /^[A-Z]/;

/**
 * Matches a valid UPPER_SNAKE_CASE identifier, for example `FOO`, `FOO_BAR`
 * or `FOO_BAR_1`.
 */
const UPPER_SNAKE_CASE = /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/;

/**
 * Returns true when the supplied metamodel `$class` refers to an enum
 * declaration.
 * @param {string} declarationClass the value of the declaration's `$class`
 * @returns {boolean} true if the declaration is an enum
 */
function isEnumDeclaration(declarationClass: string): boolean {
    return typeof declarationClass === 'string' && declarationClass.endsWith('.EnumDeclaration');
}

/**
 * Normalises the supplied, JSON serialized, AST into an array of model
 * objects. The linter accepts either a single model, an array of models or
 * the `{ models: [...] }` shape returned by `Parser.parseModels`.
 * @param {any} parsed the parsed AST
 * @returns {Array<any>} an array of model objects
 */
function getModels(parsed: any): Array<any> {
    if (Array.isArray(parsed)) {
        return parsed;
    }
    if (parsed && Array.isArray(parsed.models)) {
        return parsed.models;
    }
    return [parsed];
}

/**
 * Lints a JSON serialized Concerto model AST and reports naming convention
 * violations.
 *
 * The following rules are enforced:
 * - Type declarations (concept, asset, participant, transaction, event, enum
 *   and scalar) must use camelCase, i.e. they must not begin with an
 *   uppercase letter.
 * - Properties (fields) of non-enum types must use PascalCase, i.e. they must
 *   begin with an uppercase letter.
 * - Enum constants must use UPPER_SNAKE_CASE.
 *
 * @param {string} ast a JSON serialized Concerto model AST
 * @returns {Promise<Array<any>>} a promise that resolves to an array of
 * violation objects. The array is empty when no violations are found.
 */
export async function lintAST(ast: string): Promise<Array<any>> {
    const violations: LintViolation[] = [];

    let parsed: any;
    try {
        parsed = typeof ast === 'string' ? JSON.parse(ast) : ast;
    } catch (err) {
        throw new Error('Failed to parse AST: ' + (err as Error).message);
    }

    const models = getModels(parsed);

    models.forEach((model) => {
        if (!model || !Array.isArray(model.declarations)) {
            return;
        }
        const namespace: string = model.namespace || '';

        model.declarations.forEach((declaration: any, declarationIndex: number) => {
            if (!declaration || typeof declaration.name !== 'string') {
                return;
            }
            const declarationName: string = declaration.name;

            // Rule: type declarations must be camelCase (must not start uppercase).
            if (STARTS_WITH_UPPERCASE.test(declarationName)) {
                violations.push({
                    rule: 'type-declaration-camel-case',
                    message: `Type declaration '${declarationName}' should be camelCase`,
                    name: declarationName,
                    namespace,
                    path: ['declarations', declarationIndex, 'name'],
                    severity: 'warning',
                });
            }

            if (!Array.isArray(declaration.properties)) {
                return;
            }

            const isEnum = isEnumDeclaration(declaration.$class);

            declaration.properties.forEach((property: any, propertyIndex: number) => {
                if (!property || typeof property.name !== 'string') {
                    return;
                }
                const propertyName: string = property.name;
                const path = ['declarations', declarationIndex, 'properties', propertyIndex, 'name'];

                if (isEnum) {
                    // Rule: enum constants must be UPPER_SNAKE_CASE.
                    if (!UPPER_SNAKE_CASE.test(propertyName)) {
                        violations.push({
                            rule: 'enum-constant-upper-snake-case',
                            message: `Enum constant '${propertyName}' should be UPPER_SNAKE_CASE`,
                            name: propertyName,
                            namespace,
                            path,
                            severity: 'warning',
                        });
                    }
                } else {
                    // Rule: properties of non-enum types must be PascalCase
                    // (must start with an uppercase letter).
                    if (!STARTS_WITH_UPPERCASE.test(propertyName)) {
                        violations.push({
                            rule: 'property-pascal-case',
                            message: `Property '${propertyName}' should be PascalCase`,
                            name: propertyName,
                            namespace,
                            path,
                            severity: 'warning',
                        });
                    }
                }
            });
        });
    });

    return violations;
}

export default lintAST;
